 const page=list.slice(state.page*40,state.page*40+40);
 $('#student-list').innerHTML=`<div class="table-wrap"><table><thead><tr><th>שם התלמיד</th><th>תעודת זהות</th><th>כיתת אם</th><th>התאמות פעילות</th><th>מצב</th><th></th></tr></thead><tbody>${page.map(s=>`<tr class="${s.active?'':'removed'}"><td class="name-cell">${h(s.name)||'חסר שם'}</td><td class="id">${h(s.id)}</td><td>${h(classLabel(s))}</td><td>${h(accommodationText(s))}</td><td><span class="pill ${!s.active?'grey':keys.has(s.key)?'warning':''}">${!s.active?'הוסר':keys.has(s.key)?'דורש טיפול':'נבדק'}</span>${hasManual(s)?'<span class="pill grey">תיקון ידני</span>':''}</td><td><button class="button small ghost" data-edit="${h(s.key)}">בדיקה ועריכה</button></td></tr>`).join('')}</tbody></table></div>${!list.length?'<div class="empty">לא נמצאו תלמידים שמתאימים לחיפוש.</div>':''}<div class="toolbar" style="margin:16px 0 0"><span class="tiny muted">${list.length} תלמידים · עמוד ${state.page+1} מתוך ${Math.max(1,Math.ceil(list.length/40))}</span><div class="actions">${button('page-prev','הקודם','small ghost',state.page===0)}${button('page-next','הבא','small ghost',(state.page+1)*40>=list.length)}</div></div>`;
 $$('[data-edit]').forEach(b=>b.onclick=()=>editStudent(b.dataset.edit));$('#page-prev').onclick=()=>{state.page--;renderStudentList();};$('#page-next').onclick=()=>{state.page++;renderStudentList();};
